import { defineConfig, devices } from '@playwright/test';

/**
 * Browser-level verification against the real local stack (Task 10, R72/R73).
 *
 * The web app is started by Playwright with `VITE_API_URL` pinned to the local
 * BFF (:8787) so the spec exercises the real `/search`, `/plan` and `/sources`
 * responses, not MSW. The service worker is generated by `vite build` and is
 * not registered by the dev server; this run therefore covers the live flow,
 * while `npm run perf:web` runs Lighthouse against the built preview app where
 * the generated service worker is actually served.
 *
 * Geolocation is granted at the Buendia end of the MRT-3 corridor
 * (14.5547, 121.0244), not at Cubao: `/plan` takes its origin from the device
 * and the destination from the search selection, and Cubao → Cubao returns no
 * itineraries from the live BFF. Buendia → Cubao returns the real 4-option
 * corridor (1–5 tolerated by the spec). The choice is recorded in
 * `.superpowers/sdd/2026-11-01-biyahey-pwa-mvp/task-10-report.md`.
 */
const baseURL = 'http://localhost:5173';

export default defineConfig({
  testDir: './e2e',
  fullyParallel: false,
  forbidOnly: process.env.CI === 'true',
  retries: process.env.CI === 'true' ? 1 : 0,
  workers: 1,
  timeout: 120_000,
  expect: { timeout: 15_000 },
  reporter: process.env.CI === 'true' ? [['list'], ['html', { open: 'never' }]] : 'list',
  use: {
    baseURL,
    ...devices['Pixel 7'],
    // Pixel 7 emulation with the design's 390x844 layout viewport.
    viewport: { width: 390, height: 844 },
    permissions: ['geolocation'],
    geolocation: { latitude: 14.5547, longitude: 121.0244 },
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  webServer: {
    // Dev (not preview) keeps the E2E run independent of a prior build; the
    // BFF CORS allow-list from R40 includes localhost:5173.
    command: 'npm run dev --workspace @biyahey/web',
    url: baseURL,
    cwd: '../..',
    reuseExistingServer: process.env.CI !== 'true',
    timeout: 120_000,
    env: {
      VITE_API_URL: process.env.VITE_API_URL ?? 'http://localhost:8787',
    },
  },
});
